mapper.select:
SELECT
    #{teacherNo} as teacherNo,
    (SELECT name FROM teacher WHERE teacher_no = #{teacherNo}) as teacherName,
    (SELECT COUNT(*) FROM course_arrangement WHERE teacher_no = #{teacherNo}

            AND semester = #{semester}

    ) as courseCount,
    (SELECT COALESCE(SUM(weekly_hours * 16), 0) FROM course_arrangement WHERE teacher_no = #{teacherNo}

            AND semester = #{semester}

    ) as totalHours,
    (SELECT COUNT(DISTINCT student_id) FROM score s
        JOIN course_arrangement ca ON s.course_arrangement_id = ca.id
        WHERE ca.teacher_no = #{teacherNo}

            AND ca.semester = #{semester}

    ) as studentCount,
    (SELECT COUNT(*) FROM exam_arrangement ea
        JOIN course_arrangement ca ON ea.course_arrangement_id = ca.id
        WHERE ca.teacher_no = #{teacherNo}

            AND ca.semester = #{semester}

    ) as examCount,
    (SELECT COUNT(*) * 2 FROM invigilator_arrangement ia
        JOIN exam_arrangement ea ON ia.exam_arrangement_id = ea.id
        JOIN course_arrangement ca ON ea.course_arrangement_id = ca.id
        WHERE ia.teacher_no = #{teacherNo}

            AND ca.semester = #{semester}

    ) as invigilateHours,
    (SELECT COUNT(*) FROM score s
        JOIN course_arrangement ca ON s.course_arrangement_id = ca.id
        WHERE ca.teacher_no = #{teacherNo}

            AND ca.semester = #{semester}

    ) as totalScoreRecords

SELECT t.teacher_no as teacherNo, t.name as teacherName, COUNT(DISTINCT ca.id) as courseCount, COALESCE(SUM(ca.weekly_hours * 16), 0) as totalHours, COUNT(DISTINCT s.student_id) as studentCount FROM teacher t LEFT JOIN course_arrangement ca ON t.teacher_no = ca.teacher_no
AND ca.semester = #{semester}
LEFT JOIN score s ON ca.id = s.course_arrangement_id
t.college_code = #{collegeCode}
GROUP BY t.teacher_no, t.name ORDER BY totalHours DESC

